flex:1;min-width:160px}.menu-info strong{display:block}.menu-info small{color:#718078;overflow-wrap:anywhere}.menu-actions{display:flex;gap:6px;flex-wrap:wrap}.menu-actions form{margin:0}.child-list{margin:6px 0 6px 35px;padding:5px 10px;border-left:2px solid #dcebe3;background:#f8fbf9;border-radius:0 9px 9px 0}.child-list:empty:after{content:'Alt menü öğelerini buraya sürükleyin';display:block;color:#a0aaa4;font-size:12px;padding:8px}.status{font-size:12px;font-weight:800}.save-order{margin-top:12px}.save-state{font-size:13px;color:#176b50;margin-left:8px}@media(max-width:650px){.wrap{margin:14px auto;padding:0 12px}.top{display:flex;flex-direction:column;align-items:stretch;gap:12px;margin-bottom:20px}.top>div{width:100%;flex:1 1 auto}.top h1{font-size:25px;margin-bottom:8px}.top p{font-size:13px;line-height:1.65}.top>a{align-self:flex-start;max-width:100%;text-align:center}.form-grid{grid-template-columns:minmax(0,1fr);gap:14px}.field,.field.full{grid-column:1;min-width:0}.panel{padding:15px;margin:13px 0;border-radius:12px}.section-title{font-size:19px;margin-bottom:8px}.hint{font-size:12px;line-height:1.65;margin-top:6px}.panel form{min-width:0}.actions{gap:8px}.actions .btn{max-width:100%}.menu-row{align-items:flex-start;gap:8px}.menu-info{min-width:0;flex:1 1 100%}.menu-actions{width:100%;padding-left:0}.menu-actions .btn{padding:9px 10px;font-size:12px}.child-list{margin-left:12px;padding:5px 7px}.menu-group{padding:11px}.save-state{display:block;margin:8px 0 0}}

