<div class="field"><label for="menu-parent"><?= e(villa_ui('Üst menü / ana öğe')) ?></label><select id="menu-parent" name="parent_id"><option value="0"><?= e(villa_ui('Ana menü öğesi (üst seviye)')) ?></option><?php foreach(($items??[]) as $parent): if((int)$parent['id']===$editingId||!empty($parent['parent_id']))continue; ?><option value="<?= (int)$parent['id'] ?>" data-location="<?= e($parent['location']) ?>" <?= (int)($editItem['parent_id']??0)===(int)$parent['id']?'selected':'' ?>><?= e($parent['label']) ?> · <?= $parent['location']==='footer'?villa_ui('Alt menü'):villa_ui('Üst menü') ?></option><?php endforeach; ?></select><div class="hint"><?= e(villa_ui('Bir ana öğe seçerseniz bu bağlantı onun açılır alt menüsünde görünür.')) ?></div></div>
