<div class="field"><label for="menu-sort"><?= e(villa_ui('Sıralama')) ?></label><input id="menu-sort" type="number" name="sort_order" min="0" max="9999" value="<?= (int)($editItem['sort_order']??10) ?>"></div>
<div class="field"><label><?= e(villa_ui('Yayın durumu')) ?></label><label class="check"><input type="checkbox" name="is_active" value="1" <?= !isset($editItem['is_active'])||(int)$editItem['is_active']===1?'checked':'' ?>> <?= e(villa_ui('Menüde aktif olarak göster')) ?></label></div>
</div><div class="actions"><button class="btn" type="submit"><?= $editingId?villa_ui('Değişiklikleri kaydet'):villa_ui('Menüyü ekle') ?></button><?php if($editingId): ?><a class="btn secondary" href="<?= e(app_url('/admin/navigation')) ?>"><?= e(villa_ui('Vazgeç')) ?></a><?php endif; ?></div>
