<section class="panel"><h2 class="section-title"><?= e(villa_ui('Menü sıralaması ve hiyerarşisi')) ?></h2><p class="hint"><?= e(villa_ui('Tutma simgesinden sürükleyerek sıralayın. Bir öğeyi başka bir ana öğenin altına sürükleyerek alt menü yapabilir; isterseniz formdaki “Üst menü / ana öğe” alanını da kullanabilirsiniz.')) ?></p>
<?php foreach(['header'=>villa_ui('Üst menü'),'footer'=>villa_ui('Alt menü')] as $location=>$heading): ?><div class="menu-group"><h3><?= $heading ?></h3><ol class="sortable-list root-list" data-location="<?= $location ?>" data-parent="0">
<?php foreach($groups[$location] as $root): ?><li class="menu-node" data-id="<?= (int)$root['id'] ?>" data-location="<?= $location ?>" data-level="root" draggable="true"><div class="menu-row"><span class="drag-handle" title="<?= e(villa_ui('Sürükleyerek sırala')) ?>">⠿</span><div class="menu-info"><strong><?= e($root['label']) ?></strong><small><?= e($root['url']) ?> · #<?= (int)$root['id'] ?></small></div><span class="status" style="color:<?= (int)$root['is_active']?'#176b50':'#a43' ?>"><?= (int)$root['is_active']?villa_ui('Aktif'):villa_ui('Pasif') ?></span><div class="menu-actions"><a class="btn secondary" href="<?= e(app_url('/admin/navigation?edit='.(int)$root['id'].'#menu-form')) ?>"><?= e(villa_ui('Düzenle')) ?></a><form method="post" action="<?= e(app_url('/admin/navigation/toggle')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$root['id'] ?>"><button class="btn warning" type="submit"><?= (int)$root['is_active']?villa_ui('Pasifleştir'):villa_ui('Etkinleştir') ?></button></form><form method="post" action="<?= e(app_url('/admin/navigation/delete')) ?>" onsubmit="return confirm(<?= e(json_encode(villa_ui('Bu menü öğesi silinsin mi?'))) ?>)"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$root['id'] ?>"><button class="btn danger" type="submit"><?= e(villa_ui('Sil')) ?></button></form></div></div>
<ol class="sortable-list child-list" data-location="<?= $location ?>" data-parent="<?= (int)$root['id'] ?>"><?php foreach(($children[(int)$root['id']]??[]) as $child): ?><li class="menu-node" data-id="<?= (int)$child['id'] ?>" data-location="<?= $location ?>" data-level="child" draggable="true"><div class="menu-row"><span class="drag-handle">⠿</span><div class="menu-info"><strong>↳ <?= e($child['label']) ?></strong><small><?= e($child['url']) ?> <?= e(villa_ui('· Alt menü')) ?></small></div><span class="status" style="color:<?= (int)$child['is_active']?'#176b50':'#a43' ?>"><?= (int)$child['is_active']?villa_ui('Aktif'):villa_ui('Pasif') ?></span><div class="menu-actions"><a class="btn secondary" href="<?= e(app_url('/admin/navigation?edit='.(int)$child['id'].'#menu-form')) ?>"><?= e(villa_ui('Düzenle')) ?></a><form method="post" action="/admin/navigation/toggle"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$child['id'] ?>"><button class="btn warning" type="submit"><?= (int)$child['is_active']?villa_ui('Pasifleştir'):villa_ui('Etkinleştir') ?></button></form><form method="post" action="/admin/navigation/delete" onsubmit="return confirm(<?= e(json_encode(villa_ui('Bu menü öğesi silinsin mi?'))) ?>)"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$child['id'] ?>"><button class="btn danger" type="submit"><?= e(villa_ui('Sil')) ?></button></form></div></div></li><?php endforeach; ?></ol>
</li><?php endforeach; ?></ol></div><?php endforeach; ?>
<button class="btn save-order" id="saveMenuOrder" type="button"><?= e(villa_ui('Sıralamayı kaydet')) ?></button><span class="save-state" id="saveMenuState" aria-live="polite"></span>
</section></main>
<script>
(function(){
var picker=document.getElementById('menu-page'),url=document.getElementById('menu-url'),loc=document.getElementById('menu-location'),parent=document.getElementById('menu-parent');
if(picker&&url)picker.addEventListener('change',function(){if(picker.value)url.value=picker.value;});
function filterParents(){if(!parent||!loc)return;Array.from(parent.options).forEach(function(o){if(o.value!=='0')o.hidden=o.dataset.location!==loc.value;});if(parent.selectedOptions[0]&&parent.selectedOptions[0].hidden)parent.value='0';}
if(loc)loc.addEventListener('change',filterParents);filterParents();
var dragged=null;
document.querySelectorAll('.menu-node').forEach(function(node){
 node.addEventListener('dragstart',function(e){e.stopPropagation();dragged=node;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',node.dataset.id);node.classList.add('dragging');});
 node.addEventListener('dragend',function(e){e.stopPropagation();node.classList.remove('dragging');document.querySelectorAll('.drop-target').forEach(function(x){x.classList.remove('drop-target')});dragged=null;});
});
document.querySelectorAll('.sortable-list').forEach(function(list){
 list.addEventListener('dragover',function(e){if(!dragged||dragged.dataset.location!==list.dataset.location||dragged.contains(list))return;if(list.classList.contains('child-list')&&dragged.dataset.level==='root'&&dragged.querySelector(':scope > .child-list > .menu-node'))return;e.preventDefault();var after=null;Array.from(list.querySelectorAll(':scope > .menu-node')).forEach(function(el){if(el===dragged)return;var r=el.getBoundingClientRect();if(e.clientY<r.top+r.height/2&&!after)after=el;});if(after)list.insertBefore(dragged,after);else list.appendChild(dragged);dragged.dataset.level=list.classList.contains('root-list')?'root':'child';});
 list.addEventListener('drop',function(e){if(!dragged||dragged.dataset.location!==list.dataset.location)return;e.preventDefault();});
});
var save=document.getElementById('saveMenuOrder'),state=document.getElementById('saveMenuState');
if(save)save.addEventListener('click',async function(){
 var tree={header:[],footer:[]};
 document.querySelectorAll('.root-list').forEach(function(root){var loc=root.dataset.location;Array.from(root.querySelectorAll(':scope > .menu-node')).forEach(function(node){var children=node.querySelector(':scope > .child-list');tree[loc].push({id:Number(node.dataset.id),children:children?Array.from(children.querySelectorAll(':scope > .menu-node')).map(function(ch){return Number(ch.dataset.id)}):[]});});});
 var csrf=document.querySelector('input[name="_csrf"]');if(!csrf){state.textContent=<?= json_encode(villa_ui('Güvenlik anahtarı bulunamadı.'),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;return;}
 save.disabled=true;state.textContent='Kaydediliyor…';
 try{var body=new FormData();body.append('_csrf',csrf.value);body.append('tree',JSON.stringify(tree));var response=await fetch('<?= e(app_url('/admin/navigation/reorder')) ?>',{method:'POST',body:body,credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest'}});var data=await response.json();if(!response.ok||!data.ok)throw new Error(data.message||<?= json_encode(villa_ui('Sıralama kaydedilemedi.'),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>);state.textContent=<?= json_encode(villa_ui('Sıralama kaydedildi.'),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;}
 catch(err){state.textContent=err.message||<?= json_encode(villa_ui('Bir hata oluştu.'),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;}
 finally{save.disabled=false;}
});
})();
</script></body></html>